import {CARDS,BY_ID,KEYWORDS,KEYWORD_NAMES} from './cards.mjs';
import {Game,PHASE_NAMES} from './engine.mjs';
import {Tutorial,LESSONS} from './tutorial.mjs';
import {installCardPreview} from './card-preview.mjs';
import {lorePanel,installLoreFlip} from './lore-panel.mjs';
import {installCardDrag,dropHandCard} from './card-drag.mjs';
import {snapshot,combat,transitions,arrows} from './motion.mjs';
let animating=false,inspectorOpen=false,loreSide='flavor';
let guidance=new Tutorial(),guideChoice=false;
document.addEventListener('click',e=>{if(animating){e.preventDefault();e.stopImmediatePropagation();}},true);
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
let game=null,view='arena',inspect='b3',selected=new Set(),blocks={},blocker=null,stepKey='',timer=null,pauseAll=false,tutorial=false,resultShown=false,filter={q:'',faction:'all',type:'all'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=f=>f==='blue'?'Blue team':'Red team';
const art=d=>`art/${d.art}.webp`;
installLoreFlip({onFlip:side=>{loreSide=side;}});
const cardPreview=installCardPreview({root:app,renderCard:hoverCard,canShow:()=>!animating&&!modal.open&&!cardDrag.busy});
const cardDrag=installCardDrag({
  root:app,
  previewSource:node=>cardPreview.sourceFor(node),
  canStart:()=>!animating&&!modal.open&&view==='arena'&&!!game&&game.winner===null,
  describe:uid=>{const c=game.players[0].hand.find(c=>c.uid===uid);return c?game.playIssues(0,c).map(i=>i.message):['This card is no longer in your hand.'];},
  onBusy:busy=>{if(busy)clearTimeout(timer);else schedule();},
  onDragStart:()=>cardPreview.dismiss(true),
  onDrop:uid=>{const issues=dropHandCard(game,uid,chooseTarget);if(issues.length)toast(issues.join(' '));},
});
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000);}
function close(){modal.close();schedule();}
$('.close').onclick=close;modal.addEventListener('cancel',()=>setTimeout(schedule,0));modal.addEventListener('click',e=>{if(e.target===modal)close();});
function dialog(html){cardDrag.cancel();cardPreview.dismiss(true);clearTimeout(timer);$('#modalBody').innerHTML=html;if(!modal.open)modal.showModal();decorateTutorialDialog();}
async function action(fn){if(animating)return;cardPreview.dismiss(true);clearTimeout(timer);const before=game?snapshot(game):null;const lessonBefore=game?guidance.capture(game):null;animating=true;document.body.classList.add('animating');try{fn();if(game)guidance.observe(game,lessonBefore);if(before)await combat(before,game);render();if(before)await transitions(before,game);}catch(e){toast(e.message);}finally{animating=false;document.body.classList.remove('animating');if(game?.winner!==null&&game&&!resultShown){resultShown=true;recap();}cardPreview.refresh();schedule();}}
// Battlefield tiles follow MTG Arena: full-bleed art, a name bar, keyword icons and a power/toughness badge instead of status text.
const KEYWORD_ICONS={stealth:'M4 20c6-1 12-6 16-16-7 2-13 7-16 16Zm0 0 9-9',detection:'M12 20V5m-6 6 6-6 6 6',rapid:'M13 3 5 14h6l-1 7 8-11h-6z',alwaysOn:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10 3a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z',recharge:'M12 20s-8-5-8-11a4.5 4.5 0 0 1 8-2.5A4.5 4.5 0 0 1 20 9c0 6-8 11-8 11Z',overflow:'M5 6l6 6-6 6m7-12 6 6-6 6',firewall:'M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6z'};
const icon=path=>`<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="${path}"/></svg>`;
function tile(d,c,p,{stats,status,attacking,blocking,chosen}){
  const sick=d.type==='Unit'&&c.sick&&!d.keywords?.includes('rapid');
  const damage=c.damage||0,left=d.type==='Unit'?stats.toughness-damage:0;
  const states=[c.tapped&&'tapped',sick&&'new arrival',damage&&`${damage} damage`,attacking&&'attacking',blocking&&'blocking'].filter(Boolean);
  const combat=status.filter(s=>/^↳|blocker/.test(s));
  const label=`${d.name}${d.type==='Unit'?`, ${stats.power} power, ${left} of ${stats.toughness} toughness`:`, ${d.type}`}${(d.keywords||[]).map(k=>`, ${k}`).join('')}${states.length?`, ${states.join(', ')}`:''}`;
  return `<button class="card tile ${d.faction} ${p===0?'mine':'theirs'} ${attacking?'attack-selected':''} ${blocking?'block-selected':''} ${c.tapped?'tapped':''} ${chosen?'selected':''} ${sick?'sick':''}" data-motion-uid="${c.uid}" data-card="${d.id}" data-uid="${c.uid}" data-zone="field" aria-label="${esc(label)}"><div class="art" style="background-image:url('${art(d)}')"></div><div class="tile-name">${d.name}</div>${d.keywords?.length?`<div class="tile-keywords">${d.keywords.map(k=>`<span title="${esc(KEYWORD_NAMES[k])}: ${esc(KEYWORDS[k])}">${icon(KEYWORD_ICONS[k])}</span>`).join('')}</div>`:''}${d.type==='Unit'?`<span class="stats tile-pt">${stats.power}/<span class="${damage?'hurt':''}">${left}</span></span>`:`<span class="tile-kind">${d.type}</span>`}${sick?'<span class="tile-sick" title="New arrival: cannot attack this turn">z<small>z</small></span>':''}${combat.length?`<div class="card-status">${combat.join(' · ')}</div>`:''}</button>`;
}
function card(c,{zone='',p=null,detail=false}={}){const d=BY_ID[c.id||c],live=c.uid!==undefined;let status=[];if(live&&zone==='field'){if(c.tapped)status.push('Tapped');if(d.type==='Unit'&&c.sick&&!d.keywords?.includes('rapid'))status.push('New arrival');if(c.damage)status.push(`${c.damage} damage`);if(game.attacks.includes(c.uid))status.push('↗ Attacking');const a=Object.entries(blocks).find(([,bs])=>bs.includes(c.uid));if(a){const target=game.find(Number(a[0]));status.push(`↳ Blocks ${target?BY_ID[target.card.id].name:"departed attacker"}`);}const count=(blocks[c.uid]||[]).length;if(count)status.push(`${count} blocker${count===1?"":"s"}`);}const chosen=live&&(selected.has(c.uid)||blocker===c.uid||Object.values(blocks).flat().includes(c.uid));const combatStep=game&&['attack','afterAttack','block','afterBlock','endCombat'].includes(game.phase);const attacking=live&&zone==='field'&&combatStep&&(game.attacks.includes(c.uid)||(game.phase==='attack'&&selected.has(c.uid)));const blocking=live&&zone==='field'&&combatStep&&(blocker===c.uid||Object.values(blocks).flat().includes(c.uid)||Object.values(game.blocks).flat().includes(c.uid));const stats=live&&p!==null&&zone==='field'?game.stats(c,p):{power:d.power,toughness:d.toughness};if(live&&zone==='field'&&!detail)return tile(d,c,p,{stats,status,attacking,blocking,chosen});return `<${detail?'div':'button'} class="card ${d.faction} ${attacking?'attack-selected':''} ${blocking?'block-selected':''} ${c.tapped&&zone==='field'?'tapped':''} ${chosen?'selected':''} ${game&&zone==='hand'&&game.legal(0,c)?'playable':''}" ${detail?'':`data-motion-uid="${c.uid||''}" data-card="${d.id}" data-uid="${c.uid||''}" data-zone="${zone}" aria-label="${esc(d.name)}${d.type==='Unit'?`, ${stats.power} power, ${stats.toughness} toughness`:''}"`}><div class="card-top"><span class="card-title">${d.name}</span><span class="cost">${d.type==='Infrastructure'?'◇':d.cost}</span></div><div class="art" role="img" aria-label="${esc(d.name)} cyberpunk illustration" style="background-image:url('${art(d)}')"></div><div class="card-type">${d.type}${d.subtype?' · '+d.subtype:''}</div><div class="card-text">${d.text||'Deploy this unit to attack or block.'}</div>${status.length?`<div class="card-status">${status.join(' · ')}</div>`:''}<div class="card-bottom"><span>${d.faction.toUpperCase()} / FB1</span>${d.type==='Unit'?`<span class="stats">${stats.power}/${stats.toughness}</span>`:'<span>◇</span>'}</div></${detail?'div':'button'}>`;}
function playStatus(c){
  if(!game||!c)return '';
  const issues=game.playIssues(0,c);
  return issues.length?`<div class="play-status"><strong>Cannot play yet</strong><ul>${issues.map(issue=>`<li>${esc(issue.message)}</li>`).join('')}</ul></div>`:'<div class="play-status ready"><strong>Ready to play</strong></div>';
}
function hoverCard(el){
  const id=el.dataset.card,zone=el.dataset.zone,uid=Number(el.dataset.uid);
  const found=uid?game?.find(uid):null,c=found?.card,d=BY_ID[id];
  if(!d)return '';
  return `${card(c||id,{detail:true,zone,p:found?.p??null})}<blockquote class="preview-flavor">“${esc(d.flavor)}”</blockquote>${zone==='hand'?playStatus(c):''}${d.keywords?.length?`<div class="preview-keywords">${d.keywords.map(k=>`<p><strong>${esc(KEYWORD_NAMES[k])}.</strong> ${esc(KEYWORDS[k])}</p>`).join('')}</div>`:''}`;
}
function showCard(id,uid=null,zone=''){const d=BY_ID[id],c=uid?game?.find(uid)?.card:null,can=c&&zone==='hand'&&game.legal(0,c);dialog(`<div class="eyebrow">FIRST BREACH / ${d.faction.toUpperCase()} TEAM</div><div class="modal-card">${card(c||id,{detail:true})}<div><h2>${d.name}</h2>${lorePanel(d,loreSide)}${(d.keywords||[]).map(k=>`<p><strong>${KEYWORD_NAMES[k]}</strong><br>${KEYWORDS[k]}</p>`).join('')}${zone==='hand'?`<div id="castRequirements">${playStatus(c)}</div><button id="cast" class="primary" aria-describedby="castRequirements" ${can?'':'disabled'}>${d.type==='Infrastructure'?'Play infrastructure':'Cast card'}${d.cost?' · '+d.cost+' compute':''}</button>`:''}</div></div>`);if($('#cast'))$('#cast').onclick=()=>chooseTarget(uid);}
function chooseTarget(uid){const c=game.players[0].hand.find(c=>c.uid===uid);if(!c)return;const d=BY_ID[c.id],ts=game.targets(0,c);if(!d.target){modal.close();action(()=>game.play(0,uid));return;}if(d.target==='opponent'){modal.close();action(()=>game.play(0,uid,ts[0]));return;}dialog(`<div class="eyebrow">CAST ${d.name.toUpperCase()}</div><h2>Choose a target.</h2><p class="muted">${d.text}</p><div class="targets">${ts.map((t,i)=>{const f=t.kind==='card'?game.find(t.uid):null;return `<button data-target="${i}">${esc(game.targetName(t))}<small class="muted">${f?` · ${f.p===0?'Yours':'Opponent’s'} · ${f.zone==='grave'?'Discard':BY_ID[f.card.id].type}`:' · On the stack'}</small></button>`;}).join('')}</div>`);document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{modal.close();action(()=>game.play(0,uid,ts[Number(b.dataset.target)]));});}
function start(f,optIn=false){cardPreview.dismiss(true);clearTimeout(timer);guidance=new Tutorial(optIn);guideChoice=false;tutorial=false;stepKey='';game=new Game(f);view='arena';selected.clear();blocks={};blocker=null;resultShown=false;inspect=f==='blue'?'b3':'r3';modal.close();render();const initial=snapshot(game);initial.cards=new Map();initial.visual=new Map();animating=true;document.body.classList.add('animating');transitions(initial,game).finally(()=>{animating=false;document.body.classList.remove('animating');cardPreview.refresh();schedule();});}
function startScreen(){return `<div class="start"><div class="start-top"><div><div class="eyebrow">FIRST BREACH • SOLO TRAINING</div><h1>Choose your side.</h1></div><p>Two perspectives. One battlefield.<br>Learn how attacks unfold—and how good defenses change the outcome.</p></div><label class="tutorial-opt-in"><input id="guideFirstGame" type="checkbox" ${guideChoice?'checked':''} aria-describedby="tutorialOffer"><span><strong>Guide my first game</strong><small id="tutorialOffer">Optional · Six hands-on lessons as you play either faction. Exit anytime.</small></span></label><div class="factions">${['blue','red'].map(f=>`<article class="faction ${f}"><div class="banner" style="background-image:url('art/${f}-infrastructure.png')"></div><div class="faction-body"><img class="faction-crest" src="art/${f}-emblem.png" alt="" width="100" height="100"><div class="eyebrow">${f==='blue'?'01 / DEFEND & DISRUPT':'02 / INFILTRATE & PRESSURE'}</div><h2>${label(f)}</h2><p>${f==='blue'?'Build resilient defenses. Investigate threats. Take back control.':'Find the opening. Build your foothold. Push the advantage.'}</p><div class="tags"><span class="tag">60-card starter</span><span class="tag">25 unique cards</span><span class="tag">20 capacity</span></div><button class="primary" data-start="${f}">Play ${f} team →</button></div></article>`).join('')}</div><div class="start-foot"><span>01 &nbsp; Play infrastructure &nbsp; / &nbsp; 02 &nbsp; Deploy units &nbsp; / &nbsp; 03 &nbsp; Attack & respond</span><span>Vs. computer · 15–25 min target</span></div><p class="footer-note">Original learning game inspired by trading-card mechanics. Each card includes a security lesson. Match duration and balance are still being playtested.</p></div>`;}
function opening(){return `<div class="start">${guidedPanel()}<div class="eyebrow">${label(game.players[0].faction).toUpperCase()} / OPENING HAND</div><h1>Plan your first move.</h1><p class="muted">Aim for two or three infrastructure cards and a few low-cost units. You play first and skip your first draw.</p><div class="notice">${game.mulligans?`<strong>Select ${game.mulligans} card${game.mulligans===1?'':'s'} to put on the bottom of your deck.</strong> Selected: ${selected.size}/${game.mulligans}`:'Keep these seven cards, or shuffle and draw seven again. Each mulligan means putting one more card on the bottom when you keep.'}</div><div class="opening-hand">${game.players[0].hand.map(c=>card(c,{zone:'opening'})).join('')}</div><div class="toolbar"><button class="primary" id="keep" ${selected.size!==game.mulligans?'disabled':''}>Keep hand${game.mulligans?` · Bottom ${game.mulligans}`:''}</button><button id="mulligan" ${game.mulligans===7?'disabled':''}>Mulligan${game.mulligans?` (${game.mulligans})`:''}</button><button id="quit">Choose another faction</button></div><p class="footer-note">Click a card to inspect it${game.mulligans?' or choose it for the bottom of your deck':''}. You can inspect cards at any time in the card library.</p></div>`;}
function playerBar(p){const q=game.players[p];return `<div data-player="${p}" class="player-bar ${p===0?'you':''} ${game.actor()===p?'has-priority':''}"><div class="avatar" style="color:var(--${q.faction})"><img class="faction-emblem" src="art/${q.faction}-emblem.png" alt="${label(q.faction)} emblem" width="64" height="64"></div><div class="player-info"><strong>${p===0?'YOU':'COMPUTER'} / ${label(q.faction)}</strong><small>${game.actor()===p?'Your action':game.active===p?'Active turn':'On standby'} · ${q.hand.length} in hand</small></div><div class="hp" style="color:var(--${q.faction})" aria-label="${p===0?'Your':'Computer'} capacity ${q.life}">${q.life}<small>CAPACITY</small></div><div class="card-piles"><div class="pile deck-pile ${q.faction}" aria-label="${q.deck.length} cards in deck"><b>${q.deck.length}</b><span>Deck</span></div><button class="pile discard-pile" data-grave="${p}" aria-label="View ${p===0?'your':'opponent’s'} discard, ${q.grave.length} cards"><b>${q.grave.length}</b><span>Discard</span></button></div></div>`;}
function resources(p){const lands=game.players[p].field.filter(c=>BY_ID[c.id].type==='Infrastructure'),ready=game.mana(p),faction=game.players[p].faction,description=`${p===0?'Your':'Opponent’s'} compute: ${ready} available of ${lands.length} total.${p===0?(game.players[0].landPlayed?' Infrastructure played this turn.':' You may play one infrastructure this turn.'):''}`;return `<div class="resources compute-pile" style="--pile-width:${Math.max(94,37+(lands.length-1)*14)}px" role="img" tabindex="0" aria-label="${description}" title="${description}"><div class="compute-stack ${faction} ${lands.length?'':'empty'}" aria-hidden="true">${lands.map((c,i)=>`<span data-motion-uid="${c.uid}" class="resource stack-layer ${c.tapped?'used':''}" style="--offset:${i*14}px"></span>`).join('')}</div><b class="compute-count" aria-hidden="true">${ready}<span>/${lands.length}</span></b></div>`;}
function zone(p){const field=game.players[p].field.filter(c=>BY_ID[c.id].type!=='Infrastructure');const name=p===0?'Your battlefield':'Opponent battlefield';return `<div class="zone-head battlefield-heading"><span class="lane-label"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z"/><path d="m8 12 3 3 5-6"/></svg>${name}</span><span class="deployed-counter" role="img" aria-label="${field.length} deployed cards" title="${field.length} deployed cards"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M5 16H3V3h12v2M9 20H7V7h12v2"/><rect x="11" y="11" width="10" height="12" rx="1"/></svg><strong aria-hidden="true">${field.length}</strong></span></div><div class="board-row">${field.length?field.map(c=>card(c,{zone:'field',p})).join(''):`<div class="empty-zone"><span>${p===0?'Deploy units, tools, and controls from your hand.':'No opposing units or controls deployed.'}</span></div>`}</div>`;}
function phaseGroup(){const p=game.phase;return ['upkeep','draw'].includes(p)?0:p==='main1'?1:['beginCombat','attack','afterAttack','block','afterBlock','endCombat'].includes(p)?2:p==='main2'?3:4;}
function hint(){if(game.winner!==null)return 'Match complete. Review the lessons from your cards.';if(game.actor()===1)return 'Computer is considering its next move…';if(game.phase==='attack')return `Select ready units to attack. ${selected.size} selected. Units that attack usually tap and cannot block next turn.`;if(game.phase==='block')return blocker?'Now select an opposing attacker to block.':'Select one of your untapped units, then select the attacker it should block. You may assign multiple blockers.';if(game.phase==='cleanup')return `Select ${game.players[0].hand.length-7} cards from your hand to discard. ${selected.size} selected.`;if(game.stack.length)return 'An effect is on the stack. Cast a Response, or pass priority to let it resolve.';if(['main1','main2'].includes(game.phase)&&game.active===0)return 'Play a card. Ready infrastructure pays its cost.';return 'You have priority. Cast a Response or continue to the next step.';}
function buttonLabel(){if(game.phase==='attack')return selected.size?`Attack with ${selected.size}`:'Skip attack';if(game.phase==='block')return Object.values(blocks).flat().length?'Confirm blocks':'Take unblocked damage';if(game.phase==='cleanup')return 'Discard selected';if(game.stack.length)return 'Pass priority';if(game.phase==='main1'&&game.active===0)return 'Go to combat';if(game.phase==='main2'&&game.active===0)return 'End turn';return 'Continue';}

function guidedPanel(){
  const lesson=game?guidance.step(game,{selected,blocks,blocker}):null;
  if(!lesson)return '';
  const finished=lesson.id==='complete'||lesson.id==='ended';
  return `<section class="guided-tutorial" aria-label="First game tutorial"><div class="tutorial-copy" role="status" aria-live="polite" aria-atomic="true"><div class="eyebrow">FIRST PLAY / ${guidance.completed.size} OF ${LESSONS.length} LESSONS</div><h2>${lesson.title}</h2><p id="tutorialInstruction">${lesson.text}</p></div><div class="tutorial-progress"><progress aria-label="Tutorial lessons completed" value="${guidance.completed.size}" max="${LESSONS.length}"></progress><ol>${LESSONS.map(([id,label])=>`<li class="${guidance.completed.has(id)?'done':''}" ${lesson.id===id?'aria-current="step"':''}><span aria-hidden="true">${guidance.completed.has(id)?'✓':'○'}</span> ${label}<span class="sr-only">${guidance.completed.has(id)?' — completed':''}</span></li>`).join('')}</ol><button id="exitTutorial" class="small">${finished?'Continue playing':'Exit tutorial'}</button></div></section>`;
}
function highlightGuidance(){
  if(view!=='arena'||!game)return;
  const lesson=guidance.step(game,{selected,blocks,blocker});
  for(const selector of lesson?.targets||[])for(const element of app.querySelectorAll(selector)){
    if(element.disabled)continue;
    element.classList.add('tutorial-target');
    element.setAttribute('aria-describedby','tutorialInstruction');
  }
}
function exitGuidance(){
  guidance.exit();guideChoice=false;
  if(modal.open)modal.close();
  render();schedule();
  ($('#advance')||$('#keep')||$('#tutorialToggle'))?.focus({preventScroll:true});
}
function decorateTutorialDialog(){
  if(!guidance.enabled||view!=='arena'||!game)return;
  const cast=$('#cast'),targets=[...modal.querySelectorAll('[data-target]')];
  const message=targets.length?'Select a legal target to cast this card.':cast&&!cast.disabled?'Use the highlighted button to play this card. Its cost is paid automatically.':'Close these details to return to the guided match.';
  const note=document.createElement('div');
  note.className='tutorial-dialog-note';
  note.innerHTML=`<p id="tutorialDialogInstruction">${message}</p><button id="exitDialogTutorial" class="small">Exit tutorial</button>`;
  $('#modalBody').prepend(note);
  for(const element of targets.length?targets:cast&&!cast.disabled?[cast]:[]){element.classList.add('tutorial-target');element.setAttribute('aria-describedby','tutorialDialogInstruction');}
  $('#exitDialogTutorial').onclick=exitGuidance;
}

function tutorialText(){if(game.phase==='block')return '<strong>Block smart.</strong> A blocker deals its power to its attacker while receiving damage back. A unit survives if damage stays below its toughness. Stealth needs Stealth or Detection to block.';if(game.stack.length)return '<strong>Responses resolve last in, first out.</strong> Players alternate priority. When both pass, the top effect resolves. You then get another chance to respond.';if(game.phase==='attack')return '<strong>Choose your attackers.</strong> New units wait a turn unless they have Rapid deploy. Always-on lets a unit attack without tapping. Keep some units ready if you need blockers.';if(game.players[0].field.length===0)return '<strong>First, build your resources.</strong> Play one Infrastructure card for free during your main phase. Each ready infrastructure pays for one compute.';if(!game.players[0].field.some(c=>BY_ID[c.id].type==='Unit'))return '<strong>Deploy a unit.</strong> The number at top right is its compute cost. Bottom-right numbers are power / toughness. Cards with bright borders can be played now.';return '<strong>Keep a Response ready.</strong> Spending all your compute leaves you unable to respond. Click any card to see its rules and security lesson.';}
function battlefield(){const can=game.actor()===0&&game.winner===null;return `<div class="workspace ${inspectorOpen?'inspector-open':''} ${guidance.enabled?'has-guidance':''}">${guidedPanel()}<section class="table" aria-label="Game arena"><div class="match-top"><div><div class="eyebrow">FIRST BREACH / TRAINING MATCH</div><h2>Turn ${game.turn} <span class="muted">/ ${PHASE_NAMES[game.phase]}</span></h2></div><div class="toolbar"><button class="small" id="inspectorToggle" aria-expanded="${inspectorOpen}" aria-controls="intelligence">${inspectorOpen?'Close details':'Card details & log'}</button><button class="small" id="quit">Leave match</button></div></div>${tutorial?`<div class="notice tutorial-step"><div>${tutorialText()}</div><button class="small" id="hideTutorial" aria-label="Hide tutorial">×</button></div>`:''}<div class="player-end opponent-end">${playerBar(1)}${resources(1)}</div><section class="battle-lane opponent-lane" aria-label="Opponent battlefield">${zone(1)}</section><div class="combat-divider"><span>${['attack','afterAttack','block','afterBlock','endCombat'].includes(game.phase)?'COMBAT':'BREACH / DEFEND'}</span></div><section class="battle-lane your-lane" aria-label="Your battlefield">${zone(0)}</section><div class="player-end your-end">${resources(0)}${playerBar(0)}</div>${game.stack.length?`<div class="effect-stack" aria-label="Pending effects"><div class="eyebrow">STACK / RESOLVES TOP FIRST</div>${[...game.stack].reverse().map(s=>`<div class="stack-item" data-motion-uid="${s.card.uid}"><strong>${BY_ID[s.card.id].name}</strong>${s.p===0?'You':'Computer'}${s.target?' → '+esc(game.targetName(s.target)):''}</div>`).join('')}</div>`:''}<div class="command-area"><div class="phase-bar" aria-label="Turn phases">${['Start','Main I','Combat','Main II','End'].map((t,i)=>`<span class="phase ${phaseGroup()===i?'current':''}" ${phaseGroup()===i?'aria-current="step"':''}>${t}</span>`).join('')}</div><div class="action-bar"><div class="hint" aria-live="polite">${hint()}</div>${game.winner!==null?'<button class="primary" id="recap">View recap</button>':`<button class="primary" id="advance" ${!can?'disabled':''}>${buttonLabel()}</button>`}</div></div><div class="hand-dock"><div class="zone-head"><span>Your hand / ${game.players[0].hand.length} cards · Drag to your battlefield</span><button class="text-button" id="tutorialToggle">${tutorial?'Hide tips':'Quick tips'}</button></div><div class="hand">${game.players[0].hand.length?game.players[0].hand.map(c=>card(c,{zone:'hand'})).join(''):'<p class="muted">Your hand is empty. Draw a card on your next turn.</p>'}</div><label class="muted priority-option"><input type="checkbox" id="pauseAll" ${pauseAll?'checked':''}> Pause at every priority window</label></div></section><aside class="sidebar" id="intelligence" ${inspectorOpen?'':'hidden'}><div class="eyebrow">CARD INTELLIGENCE</div><div id="inspection">${inspection()}</div><div class="log"><div class="eyebrow">MATCH LOG</div><ol>${game.log.slice(0,14).map(l=>`<li>${esc(l)}</li>`).join('')}</ol></div></aside></div>`;}
function inspection(){const d=BY_ID[inspect];return `<div class="inspect">${card(d.id,{detail:true})}</div>${lorePanel(d,loreSide)}`;}
function library(){return `<div class="library"><div class="library-head"><div><div class="eyebrow">FIRST BREACH / COMPLETE SET</div><h1>Card library.</h1></div><span class="pill">50 cards · 2 starter decks</span></div><p class="muted">Explore the rules, learn the security concept, and plan your next play.</p><div class="filters"><input id="search" type="search" placeholder="Search names, rules, or security concepts…" aria-label="Search cards" value="${esc(filter.q)}"><select id="factionFilter" aria-label="Filter by faction"><option value="all">Both factions</option><option value="blue" ${filter.faction==='blue'?'selected':''}>Blue team</option><option value="red" ${filter.faction==='red'?'selected':''}>Red team</option></select><select id="typeFilter" aria-label="Filter by card type"><option value="all">All card types</option>${['Infrastructure','Unit','Response','Operation','Tool','Control'].map(t=>`<option ${filter.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div id="libraryGrid" class="grid"></div><p class="footer-note">Each starter contains 24 infrastructure, two copies of each of its 12 units, and one copy of each of its 12 other cards. Artwork is shared by thematic card families.</p></div>`;}
function libraryCards(){cardPreview.dismiss(true);const cs=CARDS.filter(c=>(filter.faction==='all'||c.faction===filter.faction)&&(filter.type==='all'||c.type===filter.type)&&`${c.name} ${c.text} ${c.lesson}`.toLowerCase().includes(filter.q.toLowerCase()));$('#libraryGrid').innerHTML=cs.length?cs.map(c=>card(c.id)).join(''):'<p class="muted">No matching cards. Try another search or filter.</p>';}
function guide(){return `<article class="guide"><div class="eyebrow">FIELD GUIDE / FIRST BREACH</div><h1>Know the battlefield.</h1><p>Reduce the opposing team’s operational capacity from 20 to 0. Blue protects its organization and disrupts the red campaign. Red pressures the organization and sustains its own operation.</p><section><h2>Your first turn</h2><ol><li><strong>Keep seven cards.</strong> Mulligans redraw seven; when you keep, put one card on the bottom for each mulligan. You play first and skip your first draw.</li><li><strong>Play infrastructure.</strong> You may play one per turn during either main phase with an empty stack. It costs nothing.</li><li><strong>Spend compute.</strong> Infrastructure taps automatically to pay card costs. It stays tapped until your next untap step.</li><li><strong>Deploy units.</strong> New units cannot attack until your next turn unless they have Rapid deploy. They can block immediately if untapped.</li><li><strong>Attack, then respond.</strong> Choose attackers. The defender chooses blockers. Both players can cast Responses before damage.</li><li><strong>Finish your turn.</strong> Play more cards in Main II, then end. Discard down to seven. Damage and temporary bonuses clear at cleanup.</li></ol></section><section><h2>Reading a card</h2><p>The top-right number is its compute cost. The type line tells you when it can be played. Rules text tells you what happens. A unit’s bottom-right numbers are <strong>power / toughness</strong>: damage dealt / damage needed to defeat it in one turn.</p><table><tbody><tr><td>Infrastructure</td><td>Provides one compute when tapped. One play per turn.</td></tr><tr><td>Unit</td><td>Stays on the battlefield and can attack or block.</td></tr><tr><td>Operation</td><td>A one-time effect, cast during your main phase with an empty stack.</td></tr><tr><td>Response</td><td>A one-time effect, cast whenever you have priority.</td></tr><tr><td>Tool / Control</td><td>A lasting resource or rule modifier, cast during your main phase.</td></tr></tbody></table></section><section><h2>Priority and the stack</h2><p>After casting, the caster retains priority. Both players must pass consecutively for the newest effect to resolve. Then the active player gets priority again. When the stack is empty and both pass, the game advances.</p><p>The game skips your response windows when you have no legal Response. Enable <strong>Pause at every priority window</strong> to examine every step. During your main phase, pressing the action button passes; an opponent’s Response can give you priority again before the phase ends.</p><p>Targets are chosen when casting and checked again on resolution. If a targeted card leaves its zone, the effect fails even if that card later returns. A counter can target a Response or Operation anywhere on the stack.</p></section><section><h2>Combat</h2><p>Select your attackers, then confirm. To block, select a ready unit you control, then its attacker. Several units can block one attacker; each blocker can block only one attacker. Assignments are shown on the cards. Clicking an assigned blocker removes its assignment.</p><p>Damage happens simultaneously. Without Overflow, a blocked attacker cannot hit the player even if its blocker leaves before damage. Multiple blockers receive damage in their assignment order: lethal damage first, then remaining damage to the next. Stealth can only be blocked by Stealth or Detection.</p><p>Tapped units cannot block. Blocking does not tap a unit. Damage remains marked until cleanup. Capacity gains have no maximum.</p></section><section><h2>Keywords</h2>${Object.entries(KEYWORDS).map(([k,v])=>`<p><strong>${KEYWORD_NAMES[k]}.</strong> ${v}</p>`).join('')}<p><strong>Phishing.</strong> A source tag used by Phishing-Resistant MFA. That control prevents tagged damage to its controller; it does not prevent unit damage or unrelated attacks.</p></section><section><h2>This edition’s rules scope</h2><p>First Breach uses trading-card-style phases, priority, an effect stack, tapping, new-arrival delay, combat, mulligans, and deck-out losses. It is an original, limited rules set—not a complete Magic rules engine.</p><ul><li>Compute is a single resource. Payment automatically taps exact amounts; there is no manual mana pool or colored resource requirement.</li><li>Backup and reserve start-of-turn gains are automatic and do not use the stack. The available cards cannot respond to these gains as triggered abilities.</li><li>Combat damage allocation is automatic, in blocker assignment order. There are no first-strike, planeswalker, exile, token, or sideboard mechanics in this set.</li><li>Both decks are fixed. The computer uses a local heuristic, not a remote AI service. It makes decisions from its hand and public battlefield information.</li><li>Matches run in this browser tab. Reloading starts over. There are no accounts or online multiplayer matches in this edition.</li></ul></section><section><h2>From game to practice</h2><p>Card effects are teaching abstractions. A patch does not literally deal damage, recovery is not automatic, and no control prevents every attack. Read each card’s explanation for the real concept and its limits.</p><p>Continue learning with <a href="https://www.cisa.gov/stopransomware/ransomware-guide" target="_blank" rel="noopener">CISA’s ransomware guide</a>, <a href="https://www.cisa.gov/sites/default/files/2023-01/fact-sheet-implementing-phishing-resistant-mfa-508c.pdf" target="_blank" rel="noopener">CISA’s phishing-resistant MFA guidance</a>, and <a href="https://www.cisa.gov/news-events/cybersecurity-advisories/aa23-278a" target="_blank" rel="noopener">CISA and NSA’s common security misconfigurations</a>. The rules inspiration is documented in <a href="https://magic.wizards.com/en/rules" target="_blank" rel="noopener">Magic’s official rules</a>.</p></section><p class="footer-note">Breach & Defend is an independent educational game. It is not affiliated with or endorsed by Wizards of the Coast. Original card design and AI-generated illustrations.</p></article>`;}
function recap(){const won=game.winner===0;const unique=[...new Map(game.events.map(e=>[e.name,e])).values()];dialog(`<div class="result"><div class="eyebrow">TRAINING MATCH / COMPLETE</div><h2>${game.winner==='draw'?'Mutual shutdown':won?'Operation successful.':'Operation disrupted.'}</h2><p>${game.reason}</p><div class="tags" style="justify-content:center"><span class="tag">${game.turn} turns</span><span class="tag">${game.players[0].life} your capacity</span><span class="tag">${game.players[1].life} opponent capacity</span></div><button class="primary" id="rematch">Play again</button> <button id="chooseSide">Change faction</button></div><h3>Lessons from this match</h3>${unique.length?unique.slice(-6).map(e=>`<div class="lesson"><strong>${e.name}</strong><p>${e.lesson}</p></div>`).join(''):'<p class="muted">Play cards to discover their security lessons.</p>'}`);$('#rematch').onclick=()=>start(game.players[0].faction);$('#chooseSide').onclick=()=>{modal.close();game=null;render();};}
function render(){cardDrag.cancel();cardPreview.dismiss(true);const focused=document.activeElement;const focusId=app.contains(focused)?focused.id:null;const focusUid=app.contains(focused)?focused.dataset?.uid:null;document.body.classList.toggle("match-playing",view==="arena"&&!!game&&game.phase!=="opening");arrows({});const key=game?`${game.turn}:${game.phase}`:'';if(key!==stepKey){selected.clear();blocker=null;blocks=game?.phase==='block'?{}:structuredClone(game?.blocks||{});stepKey=key;}document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.id===`${view}Nav`));app.innerHTML=view==='library'?library():view==='guide'?guide():!game?startScreen():game.phase==='opening'?opening():battlefield();if(view==='arena'&&game)arrows(blocks);if(view==='library'){libraryCards();$('#search').oninput=e=>{filter.q=e.target.value;libraryCards();};$('#factionFilter').onchange=e=>{filter.faction=e.target.value;libraryCards();};$('#typeFilter').onchange=e=>{filter.type=e.target.value;libraryCards();};}document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start,guideChoice));if($('#guideFirstGame'))$('#guideFirstGame').onchange=e=>{guideChoice=e.target.checked;};if($('#exitTutorial'))$('#exitTutorial').onclick=exitGuidance;highlightGuidance();if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});else if(focusUid)app.querySelector(`[data-uid="${focusUid}"]`)?.focus({preventScroll:true});if($('#keep'))$('#keep').onclick=()=>action(()=>game.keep([...selected]));if($('#mulligan'))$('#mulligan').onclick=()=>action(()=>{game.mulligan();selected.clear();});if($('#advance'))$('#advance').onclick=advance;if($('#inspectorToggle'))$('#inspectorToggle').onclick=()=>{inspectorOpen=!inspectorOpen;render();$('#inspectorToggle')?.focus();};if($('#quit'))$('#quit').onclick=()=>{if(game.phase==='opening'){game=null;render();return;}dialog('<h2>Leave this match?</h2><p>Your current match will end. You can start a new match as either faction.</p><div class="toolbar"><button id="leave" class="primary">Leave match</button><button id="stay">Keep playing</button></div>');$('#leave').onclick=()=>{game=null;modal.close();render();};$('#stay').onclick=close;};if($('#recap'))$('#recap').onclick=recap;if($('#pauseAll'))$('#pauseAll').onchange=e=>{pauseAll=e.target.checked;schedule();};for(const id of ['hideTutorial','tutorialToggle'])if($('#'+id))$('#'+id).onclick=()=>{tutorial=!tutorial;render();};document.querySelectorAll('[data-grave]').forEach(b=>b.onclick=()=>{const p=Number(b.dataset.grave);dialog(`<h2>${p===0?'Your':'Opponent’s'} discard</h2><div class="grid">${game.players[p].grave.map(c=>card(c)).join('')||'<p>No discarded cards yet.</p>'}</div>`);});if(game&&game.winner!==null&&!resultShown){resultShown=true;setTimeout(()=>{if(animating)resultShown=false;else if(game?.winner!==null&&game)recap();},900);}}
function advance(){action(()=>{if(game.phase==='attack')game.attackers(0,[...selected]);else if(game.phase==='block')game.blockers(0,blocks);else if(game.phase==='cleanup')game.discard([...selected]);else game.pass(0);});}
document.addEventListener('click',e=>{if(animating)return;const el=e.target.closest('[data-card]');if(!el)return;const id=el.dataset.card,uid=Number(el.dataset.uid),zone=el.dataset.zone;inspect=id;if(view==='library'||!uid||modal.open){showCard(id);return;}if(zone==='opening'&&game.mulligans){if(selected.has(uid))selected.delete(uid);else if(selected.size<game.mulligans)selected.add(uid);render();return;}if(zone==='hand'&&game.phase==='cleanup'&&game.active===0){selected.has(uid)?selected.delete(uid):selected.add(uid);render();return;}const f=game.find(uid);if(zone==='field'&&game.actor()===0){if(game.phase==='attack'&&f.p===0){if(game.canAttack(0,f.card)){selected.has(uid)?selected.delete(uid):selected.add(uid);render();}else toast('Only ready units that are not new arrivals can attack. Firewall units cannot attack.');return;}if(game.phase==='block'){if(f.p===0){if(BY_ID[id].type!=='Unit'||f.card.tapped){toast('Choose an untapped unit to block.');return;}for(const a in blocks)blocks[a]=blocks[a].filter(x=>x!==uid);blocker=blocker===uid?null:uid;render();return;}if(blocker&&game.attacks.includes(uid)){const b=game.find(blocker).card;if(!game.canBlock(b,f.card)){toast('Stealth attackers need a blocker with Stealth or Detection.');return;}(blocks[uid]??=[]).push(blocker);blocker=null;render();return;}}}showCard(id,uid,zone);});
app.addEventListener('focusin',e=>{const el=e.target.closest('[data-card]');if(el&&$('#inspection')){inspect=el.dataset.card;$('#inspection').innerHTML=inspection();}});
app.addEventListener('pointerover',e=>{const el=e.target.closest('[data-card]');if(el&&$('#inspection')&&inspect!==el.dataset.card){inspect=el.dataset.card;$('#inspection').innerHTML=inspection();}});
window.addEventListener('resize',()=>arrows(view==='arena'?blocks:{}));
document.addEventListener('scroll',()=>arrows(view==='arena'?blocks:{}),true);
for(const name of ['arena','library','guide'])$('#'+name+'Nav').onclick=()=>{if(animating)return;view=name;clearTimeout(timer);render();schedule();};
function schedule(){clearTimeout(timer);if(animating||cardDrag.busy||!game||game.winner!==null||view!=='arena'||modal.open||game.phase==='opening')return;const actor=game.actor();if(guidance.shouldPause(game))return;if(actor===1){timer=setTimeout(()=>action(()=>game.aiAction()),450);return;}if(!pauseAll&&!['main1','main2','attack','block','cleanup'].includes(game.phase)&&!game.players[0].hand.some(c=>game.legal(0,c)))timer=setTimeout(()=>action(()=>game.pass(0)),220);else if(!pauseAll&&game.active===1&&!['attack','block','cleanup'].includes(game.phase)&&!game.players[0].hand.some(c=>game.legal(0,c)))timer=setTimeout(()=>action(()=>game.pass(0)),220);}
if(document.modelContext?.registerTool){for(const tool of [{name:'start_training_match',description:'Start a new local training match as red or blue. Replaces any current match.',inputSchema:{type:'object',properties:{faction:{type:'string',enum:['red','blue']}},required:['faction'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['red','blue'].includes(input.faction)||Object.keys(input).some(k=>k!=='faction'))throw Error('Choose red or blue.');start(input.faction);return {faction:input.faction,phase:game.phase,handSize:game.players[0].hand.length};}},{name:'read_training_match',description:'Read current public match state and your own hand. Does not reveal the computer hand.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length)throw Error('No arguments expected.');return game?{phase:game.phase,turn:game.turn,activePlayer:game.active,capacity:game.players.map(p=>p.life),hand:game.players[0].hand.map(c=>BY_ID[c.id].name),battlefield:game.players.map(p=>p.field.map(c=>BY_ID[c.id].name))}:{phase:'choose-faction'};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
render();
